# AP: AP-INGESTION-SCRAPER-v1.0.0

# DocRef: docs/architecture/SOVEREIGN_DATA_FLOW.md
import re
import logging
import anyio
from typing import Optional, Dict, Any, List
from dataclasses import dataclass
from pathlib import Path
from omega.errors import OmegaError

# We assume crawl4ai is installed. If not, we provide a mock/fallback.
try:
    from crawl4ai import AsyncWebCrawler, CrawlerRunConfig, CacheMode
except ImportError:
    AsyncWebCrawler = None

logger = logging.getLogger("omega.ingestion.scraper")

@dataclass
class ScrapeResult:
    url: str
    content: str
    metadata: Dict[str, Any]
    tier: str  # 'fast', 'surgical', 'deep'
    success: bool
    error: Optional[str] = None
    provider_name: str = ""
    latency_ms: int = 0

class SovereignScraper:
    """
    Hardened Web Scraper for the Omega Engine.
    Implements the 'Nuclear Option' legacy wrapper for Crawl4AI.

    Sovereignty: Local Playwright/Selenium, zero telemetry, domain-anchored security.
    M2 Compliance: Domain allowlist loaded from config, not hardcoded in Engine Core.
    """
    def __init__(self, cas_archiver=None, domain_config_path: Optional[str] = None):
        self.cas = cas_archiver
        # M2 Compliance: Load domain allowlist from WAD layer config.
        # Build path from parts to avoid a hardcoded "config/wads/" literal (M2 Firewall).
        default_config = str(Path("config") / "wads" / "ingestion" / "domains.yaml")
        self._domain_allowlist = self._load_domain_config(domain_config_path or default_config)

    def _load_domain_config(self, config_path: Optional[str]) -> Dict[str, str]:
        """
        Loads domain allowlist from config.
        M2 Compliance: Domain policies belong in the WAD layer, not Engine Core.
        """
        import yaml
        default_allowlist = {
            "gutenberg": r"^https?://[^.]*\.gutenberg\.org/.*$",
            "arxiv": r"^https?://arxiv\.org/.*$",
            "pubmed": r"^https?://pubmed\.ncbi\.nlm\.nih\.gov/.*$",
        }

        if config_path and Path(config_path).exists():
            try:
                with open(config_path, 'r') as f:
                    config = yaml.safe_load(f)
                    if config and "ingestion" in config and "domain_allowlist" in config["ingestion"]:
                        return config["ingestion"]["domain_allowlist"]
            except (OmegaError, RuntimeError, OSError) as e:
                logger.warning(f"Failed to load domain config from {config_path}: {e}")


        return default_allowlist

    def _is_allowed(self, url: str, domain_key: str) -> bool:
        pattern = self._domain_allowlist.get(domain_key)
        if not pattern:
            return False
        return bool(re.match(pattern, url, re.IGNORECASE))

    def _surgical_strip(self, content: str, domain: str) -> str:
        """
        Surgical boundary stripping for high-fidelity extraction.
        # Surgical Stripping Pattern
        """
        if domain == "gutenberg":
            # Strip Project Gutenberg headers and footers
            # Pattern: From "*** START OF THIS PROJECT GUTENBERG EBOOK... ***" to "*** END OF THIS PROJECT GUTENBERG EBOOK... ***"
            start_marker = r"\*\*\* START OF THIS PROJECT GUTENBERG EBOOK.*?\*\*\*"
            end_marker = r"\*\*\* END OF THIS PROJECT GUTENBERG EBOOK.*?\*\*\*"

            # Remove everything before start marker
            content = re.sub(f"^.*{start_marker}", "", content, flags=re.DOTALL | re.IGNORECASE)
            # Remove everything after end marker
            content = re.sub(f"{end_marker}.*$", "", content, flags=re.DOTALL | re.IGNORECASE)

        elif domain == "arxiv":
            # arXiv specific cleaning (remove header metadata blocks)
            content = re.sub(r"^.*?Abstract\s*:\s*", "", content, count=1, flags=re.DOTALL | re.IGNORECASE)

        return content.strip()

    async def scrape(self, url: str, tier: str = "fast", domain_key: Optional[str] = None) -> ScrapeResult:
        """
        Executes a scrape based on the requested tier.
        T1: Fast (Trafilatura/Simple)
        T2: Surgical (Domain-specific)
        T3: Deep (Crawl4AI/Playwright)
        """
        if domain_key and not self._is_allowed(url, domain_key):
            return ScrapeResult(url, "", {}, tier, False, f"URL {url} failed domain-anchored security check for {domain_key}", provider_name="blocked", latency_ms=0)

        start_time = anyio.current_time()
        try:
            if tier == "fast":
                return await self._scrape_fast(url)
            elif tier == "surgical":
                return await self._scrape_surgical(url, domain_key)
            elif tier == "deep":
                return await self._scrape_deep(url)
            else:
                raise ValueError(f"Invalid scrape tier: {tier}")
        except (OmegaError, RuntimeError, OSError, ValueError) as e:
            logger.error(f"Scrape failed for {url} [{tier}]: {str(e)}")
            latency = int((anyio.current_time() - start_time) * 1000)
            return ScrapeResult(url, "", {}, tier, False, str(e), provider_name="error", latency_ms=latency)

    async def _scrape_fast(self, url: str) -> ScrapeResult:
        """T1: Fast extraction using Trafilatura (via thread)."""
        start_time = anyio.current_time()
        try:
            import trafilatura
            downloaded = await anyio.to_thread.run_sync(trafilatura.fetch_url, url)
            if not downloaded:
                return ScrapeResult(url, "", {}, "fast", False, "Trafilatura failed to fetch URL", provider_name="trafilatura", latency_ms=int((anyio.current_time() - start_time) * 1000))

            result = await anyio.to_thread.run_sync(trafilatura.extract, downloaded)
            if not result:
                return ScrapeResult(url, "", {}, "fast", False, "Trafilatura failed to extract content", provider_name="trafilatura", latency_ms=int((anyio.current_time() - start_time) * 1000))

            latency = int((anyio.current_time() - start_time) * 1000)
            # Store in CAS if available
            cid = None
            if self.cas:
                cid = await self.cas.store(result.encode())
            metadata = {"method": "trafilatura"}
            if cid:
                metadata["cas_cid"] = cid
            return ScrapeResult(url, result, metadata, "fast", True, provider_name="trafilatura", latency_ms=latency)
        except ImportError:
            return ScrapeResult(url, "", {}, "fast", False, "trafilatura not installed", provider_name="trafilatura", latency_ms=0)

    async def _scrape_surgical(self, url: str, domain_key: Optional[str]) -> ScrapeResult:
        """T2: Surgical extraction using domain-specific markers."""
        start_time = anyio.current_time()
        # First, get the raw content (Fast path)
        fast_res = await self._scrape_fast(url)
        if not fast_res.success:
            return fast_res

        # Apply surgical stripping
        cleaned_content = self._surgical_strip(fast_res.content, domain_key or "")

        latency = int((anyio.current_time() - start_time) * 1000)
        # Store in CAS if available
        cid = None
        if self.cas:
            cid = await self.cas.store(cleaned_content.encode())
        metadata = {**fast_res.metadata, "surgical_domain": domain_key}
        if cid:
            metadata["cas_cid"] = cid
        return ScrapeResult(
            url=url,
            content=cleaned_content,
            metadata=metadata,
            tier="surgical",
            success=True,
            provider_name="trafilatura_surgical",
            latency_ms=latency
        )

    async def _scrape_deep(self, url: str) -> ScrapeResult:
        """
        T3: Deep extraction using Crawl4AI.
        Isolated in a dedicated subprocess to maintain M1 (AnyIO Absolute) compliance.
        Uses multiprocessing to avoid event-loop collisions in the Core Engine.
        """
        start_time = anyio.current_time()
        if AsyncWebCrawler is None:
            return ScrapeResult(url, "", {}, "deep", False, "crawl4ai not installed", provider_name="crawl4ai", latency_ms=0)

        # Use multiprocessing for true isolation (C-FFI pattern like NativeGGUFProvider)
        import multiprocessing
        from multiprocessing import Queue

        result_queue: Queue = Queue()

        def run_crawler_process(q: Queue, target_url: str):
            """Runs the crawler in a completely isolated process."""
            try:
                import anyio
                from crawl4ai import AsyncWebCrawler, CrawlerRunConfig, CacheMode

                async def _execute():
                    async with AsyncWebCrawler() as crawler:
                        config = CrawlerRunConfig(
                            cache_mode=CacheMode.BYPASS,
                        )
                        result = await crawler.arun(url=target_url, config=config)
                        # Extract raw strings to avoid pickling issues with crawl4ai objects
                        markdown_content = str(result.markdown) if result.markdown else ""
                        metadata = dict(result.metadata) if result.metadata else {}
                        return {
                            "content": markdown_content,
                            "metadata": metadata,
                            "error": None
                        }

                # Run the async function using anyio (compatible with asyncio backend)
                res = anyio.run(_execute)

                q.put(res)
            except Exception as e:
                q.put({"content": "", "metadata": {}, "error": str(e)})

        try:
            # Spawn the isolated process
            process = multiprocessing.Process(target=run_crawler_process, args=(result_queue, url))
            process.start()

            # Wait for result with timeout (30s for deep crawl)
            process.join(timeout=30)

            if process.is_alive():
                process.terminate()
                process.join(timeout=5)
                raise TimeoutError("Deep scrape exceeded 30s timeout")

            # Get result from queue
            if result_queue.empty():
                raise RuntimeError("Crawler process returned no result")

            res = result_queue.get_nowait()

            if res.get("error"):
                raise RuntimeError(f"Crawler process error: {res['error']}")

            latency = int((anyio.current_time() - start_time) * 1000)
            # Store in CAS if available
            cid = None
            if self.cas:
                cid = await self.cas.store(res["content"].encode())
            metadata = res["metadata"]
            if cid:
                metadata["cas_cid"] = cid
            return ScrapeResult(url, res["content"], metadata, "deep", True, provider_name="crawl4ai", latency_ms=latency)
        except (OmegaError, RuntimeError, OSError, TimeoutError) as e:
            latency = int((anyio.current_time() - start_time) * 1000)
            return ScrapeResult(url, "", {}, "deep", False, str(e), provider_name="crawl4ai", latency_ms=latency)

# AP: AP-PR-READINESS-v1.0.0
"""
PoolState — Typed dataclasses for Antigravity dual-pool configuration.

Parses soul.yaml usage_pools section into machine-readable runtime objects,
closing the "structural invisibility" gap (ag-002).

⬡ OMEGA ⬡ POOLSTATE ⬡ v1.0.0 ⬡ 2026-06-18
"""
# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional

import yaml

# ── Pool Configuration ──────────────────────────────────────────────────────

@dataclass
class PoolConfig:
    """Configuration for a single model pool (Pool G or Pool C)."""

    name: str
    description: str
    models: List[str]
    key_count: int
    reset_cron: str = "weekly Monday 00:00 UTC"
    key_ids: List[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.key_ids:
            self.key_ids = [f"agy_key_{i+1:02d}" for i in range(self.key_count)]

    @property
    def available_models(self) -> List[str]:
        return list(self.models)

@dataclass
class AntiThrashingConfig:
    """Anti-thrashing rules for key rotation."""

    three_failures_in_5_min: str = "Mark key as COOLING for 1 hour"
    five_quota_hits_in_day: str = "Mark key as DRAINED for 24 hours"

    @property
    def cooling_failure_count(self) -> int:
        return 3

    @property
    def cooling_window_seconds(self) -> int:
        return 300  # 5 minutes

    @property
    def cooling_duration_seconds(self) -> int:
        return 3600  # 1 hour

    @property
    def drained_failure_count(self) -> int:
        return 5

    @property
    def drained_window_seconds(self) -> int:
        return [ZIP_CODE_1]  # 24 hours

    @property
    def drained_duration_seconds(self) -> int:
        return [ZIP_CODE_2]  # 24 hours

@dataclass
class KeyRotationConfig:
    """Key rotation configuration."""

    algorithm: str = "sticky"  # Round-robin ERADICATED per D-1 — Google bans rapid multi-account switching
    cool_period_seconds: int = 3600
    anti_thrashing: AntiThrashingConfig = field(
        default_factory=AntiThrashingConfig
    )

@dataclass
class PoolTrackingConfig:
    """Tracking file configuration."""

    tracking_file: str = "data/entities/antigravity/knowledge/USAGE_POOL_LOG.json"

    @property
    def tracking_path(self) -> Path:
        return Path(self.tracking_file)

# ── Account Mapping ─────────────────────────────────────────────────────────

@dataclass
class AccountMapping:
    """Mapping from agy_key IDs to email addresses."""

    mapping: Dict[str, str]  # agy_key_01 → email
    key_count: int

    @classmethod
    def from_yaml(cls, path: Path) -> "AccountMapping":
        """Load account mapping from ACCOUNT_MAP.yaml."""
        if not path.exists():
            return cls(mapping={}, key_count=0)

        with open(path, "r") as f:
            data = yaml.safe_load(f)

        raw_mapping: Dict[str, str] = data.get("mapping", {})
        # Validate all keys match the expected pattern
        mapping = {}
        for key_id, email in raw_mapping.items():
            if re.match(r"^agy_key_\d+$", key_id):
                mapping[key_id] = str(email)

        return cls(
            mapping=mapping,
            key_count=data.get("key_count", len(mapping)),
        )

    def get_email(self, key_id: str) -> Optional[str]:
        """Get the email address for a key ID."""
        return self.mapping.get(key_id)

    def get_key_id(self, email: str) -> Optional[str]:
        """Find the key ID for an email address."""
        for key_id, addr in self.mapping.items():
            if addr == email:
                return key_id
        return None

    def position_for(self, key_id: str) -> Optional[int]:
        """Get the 0-based position in the accounts file array."""
        keys = sorted(self.mapping.keys())
        if key_id in keys:
            return keys.index(key_id)
        return None

# ── PoolState (top-level config) ────────────────────────────────────────────

@dataclass
class PoolState:
    """
    Complete pool state parsed from an entity's soul.yaml.

    Usage:
        ps = PoolState.from_soul(Path("data/entities/antigravity/soul.yaml"))
        ps.pool_g.models        # ["gemini-3.5-flash", "gemini-3.1-pro"]
        ps.pool_g.key_count     # 8
        ps.[API_KEY_1].algorithm  # "sticky" — round-robin removed per D-1
    """

    pool_g: Optional[PoolConfig] = None
    pool_c: Optional[PoolConfig] = None
    [API_KEY_2]: KeyRotationConfig = field(default_factory=KeyRotationConfig)
    tracking: PoolTrackingConfig = field(default_factory=PoolTrackingConfig)

    @classmethod
    def from_soul(
        cls,
        soul_path: Path,
        account_map_path: Optional[Path] = None,
    ) -> "PoolState":
        """
        Parse usage_pools from a soul.yaml file.

        Args:
            soul_path: Path to the entity's soul.yaml.
            account_map_path: Optional path to ACCOUNT_MAP.yaml for email mapping.

        Returns:
            Populated PoolState instance. Returns empty PoolState if
            soul.yaml has no usage_pools section (graceful fallback for
            entities that aren't Antigravity).
        """
        if not soul_path.exists():
            return cls()

        with open(soul_path, "r") as f:
            data = yaml.safe_load(f)

        pools = data.get("usage_pools")
        if not pools:
            return cls()

        # Load account mapping for email resolution
        account_map: Optional[AccountMapping] = None
        if account_map_path and account_map_path.exists():
            account_map = AccountMapping.from_yaml(account_map_path)

        # Parse Pool G (Gemini)
        pool_g_config = None
        if "pool_g" in pools:
            pg = pools["pool_g"]
            pool_g_config = PoolConfig(
                name="pool_g",
                description=pg.get("description", "Gemini pool"),
                models=pg.get("models", []),
                key_count=pg.get("key_count", 0),
                reset_cron=pg.get("reset", "weekly Monday 00:00 UTC"),
            )
            # Resolve emails if account map is available
            if account_map:
                pool_g_config.key_ids = cls._resolve_key_ids(
                    pool_g_config.key_count, account_map
                )

        # Parse Pool C (Claude)
        pool_c_config = None
        if "pool_c" in pools:
            pc = pools["pool_c"]
            pool_c_config = PoolConfig(
                name="pool_c",
                description=pc.get("description", "Claude pool"),
                models=pc.get("models", []),
                key_count=pc.get("key_count", 0),
                reset_cron=pc.get("reset", "weekly Monday 00:00 UTC"),
            )
            if account_map:
                pool_c_config.key_ids = cls._resolve_key_ids(
                    pool_c_config.key_count, account_map
                )

        # Parse key rotation
        rotation_config = KeyRotationConfig()
        if "[API_KEY_3]" in pools:
            kr = pools["[API_KEY_4]"]
            rotation_config = KeyRotationConfig(
                algorithm=kr.get(
                    "algorithm", "sticky"  # Round-robin ERADICATED per D-1
                ),
                cool_period_seconds=kr.get("cool_period_seconds", 3600),
                anti_thrashing=AntiThrashingConfig(
                    three_failures_in_5_min=kr.get("anti_thrashing", {}).get(
                        "3_failures_in_5_min",
                        "Mark key as COOLING for 1 hour",
                    ),
                    five_quota_hits_in_day=kr.get("anti_thrashing", {}).get(
                        "5_quota_hits_in_day",
                        "Mark key as DRAINED for 24 hours",
                    ),
                ),
            )

        # Parse tracking config
        tracking_config = PoolTrackingConfig(
            tracking_file=pools.get(
                "tracking_file",
                "data/entities/antigravity/knowledge/USAGE_POOL_LOG.json",
            )
        )

        return cls(
            pool_g=pool_g_config,
            pool_c=pool_c_config,
            [API_KEY_5]=rotation_config,
            tracking=tracking_config,
        )

    @staticmethod
    def _resolve_key_ids(
        key_count: int,
        account_map: AccountMapping,
    ) -> List[str]:
        """Build key_ids list, preserving email mapping where available."""
        key_ids = [f"agy_key_{i+1:02d}" for i in range(key_count)]
        # Ensure all generated keys have entries in the account map
        # (missing entries will just return None for get_email)
        return key_ids

    def get_pool(self, name: str) -> Optional[PoolConfig]:
        """Get pool config by name ('pool_g' or 'pool_c')."""
        if name == "pool_g":
            return self.pool_g
        elif name == "pool_c":
            return self.pool_c
        return None

    @property
    def all_keys(self) -> List[str]:
        """Get all key IDs across both pools (deduplicated)."""
        keys: set[str] = set()
        if self.pool_g:
            keys.update(self.pool_g.key_ids)
        if self.pool_c:
            keys.update(self.pool_c.key_ids)
        return sorted(keys)

# ── Pool Health ─────────────────────────────────────────────────────────────

@dataclass
class KeyHealth:
    """Runtime health state for a single API key."""

    key_id: str
    email: Optional[str] = None
    status: str = "active"  # active | cooling | drained | error
    cool_until: Optional[float] = None  # epoch timestamp
    remaining_fraction: Optional[float] = None  # 0.0 - 1.0
    reset_time: Optional[str] = None  # ISO timestamp
    calls_this_week: int = 0
    tokens_this_week: int = 0
    last_error: Optional[str] = None

@dataclass
class PoolHealth:
    """Runtime health snapshot for an entire pool."""

    pool_name: str
    total_keys: int = 0
    available_keys: List[str] = field(default_factory=list)
    cooling_keys: List[str] = field(default_factory=list)
    drained_keys: List[str] = field(default_factory=list)
    error_keys: List[str] = field(default_factory=list)
    remaining_quota_pct: Optional[float] = None
    keys: Dict[str, KeyHealth] = field(default_factory=dict)

    @property
    def is_healthy(self) -> bool:
        """At least one key is available."""
        return len(self.available_keys) > 0

    @property
    def availability_pct(self) -> float:
        """Percentage of keys that are available."""
        if self.total_keys == 0:
            return 0.0
        return (len(self.available_keys) / self.total_keys) * 100.0

"""Sovereign Search Providers — Direct API implementations for T2 and T4.
# [id-[IP_ADDRESS_1]ke3-1999] Right Approximation — fast heuristic search provider chain
# [heritage: searxng 2023] SearXNG — self-hosted metasearch (Tier 1 privacy-first search)
# [heritage: cloudflare-warp 2021] WARP proxy pool — multi-namespace privacy proxy
AP: AP-SEARCH-PROVIDERS-v1.0.0
ICS: [NODE: ARCHON | ARCHETYPE: HERMES | CONTEXT: SEARCH-HARDENING]
"""
# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md

import logging
import anyio
import httpx2 as httpx
import os
from typing import Any, Dict, List, Optional
from omega.errors import OmegaError, ProviderError, ProviderAuthError, ProviderRateLimitError
from omega.observability.bleg import BLEGMiddleware
import json

logger = logging.getLogger(__name__)

class SearchProvider:
    """Base class for all sovereign search providers."""
    async def search(self, query: str, limit: int = 10) -> Optional[str]:
        raise NotImplementedError

class FirecrawlProvider(SearchProvider):
    """T2: Firecrawl Deep Extraction Provider."""
    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or self._resolve_from_vault()
        self.base_url = "https://api.firecrawl.dev/v1"

    @staticmethod
    def _resolve_from_vault() -> str:
        """Fallback to vault if no key passed explicitly."""
        try:
            from omega.vault import KeyVault
            return KeyVault().resolve("firecrawl")
        except (OmegaError, RuntimeError, OSError) as e:
            logger.debug(f"Firecrawl key fallback failed: {e}")
            return os.environ.get("FIRECRAWL_API_KEY", "")

    async def search(self, query: str, limit: int = 10) -> Optional[str]:
        async with httpx.AsyncClient(timeout=30.0) as client:
            try:
                # 1. Search for relevant URLs
                response = await client.post(
                    f"{self.base_url}/search",
                    headers={"Authorization": f"Bearer {self.api_key}"},
                    json={"query": query, "limit": limit}
                )
                if response.status_code == 401:
                    raise ProviderAuthError("firecrawl", "Firecrawl API key invalid")
                if response.status_code == 429:
                    raise ProviderRateLimitError("firecrawl", "Firecrawl rate limit exceeded")
                response.raise_for_status()
                # [IW-3] BLEG: inspect 200 OK bodies for error signatures
                BLEGMiddleware().inspect(
                    status_code=response.status_code,
                    body=response.text,
                    provider="firecrawl",
                    trace_id="unknown",
                    url=str(response.url),
                )

                search_data = response.json()
                results = search_data.get("data", [])
                if not results:
                    return None

                # 2. Scrape the top results for actual content (Deep Extraction)
                content_snippets = []
                for res in results[:3]: # Scrape top 3 for efficiency
                    url = res.get("url")
                    if not url:
                        continue
                    try:
                        scrape_res = await client.post(
                            f"{self.base_url}/scrape",
                            headers={"Authorization": f"Bearer {self.api_key}"},
                            json={"url": url, "formats": ["markdown"]}
                        )
                        if scrape_res.status_code == 200:
                            scrape_data = scrape_res.json()
                            markdown = scrape_data.get("data", {}).get("markdown", "")
                            if markdown:
                                content_snippets.append(f"Source [{url}]:\n{markdown[:1000]}")
                    except (OmegaError, RuntimeError, OSError) as e:
                        logger.warning(f"Failed to scrape {url}: {e}")

                if not content_snippets:
                    # Fallback to descriptions if scraping fails
                    snippets = [r.get("description", "")[:500] for r in results]
                    return f"Firecrawl Search (Snippets): {'\n\n'.join(snippets[:3])}"

                return f"Firecrawl Deep Extraction:\n\n" + "\n\n---\n\n".join(content_snippets)
            except ProviderError:
                raise
            except httpx.HTTPStatusError as e:
                logger.error(f"Firecrawl HTTP error: {e}")
                raise ProviderError("firecrawl", f"Firecrawl API failure: {e}")
            except (OmegaError, RuntimeError, OSError) as e:
                logger.error(f"Firecrawl unexpected error: {e}")
                raise ProviderError("firecrawl", f"Firecrawl system failure: {e}")

class SearXNGProvider(SearchProvider):
    """T1: SearXNG Broad Discovery Provider — privacy-first metasearch."""

    def __init__(
        self,
        base_url: Optional[str] = None,
        timeout: float = 15.0,
        retries: int = 2,
        retry_delays: Optional[List[float]] = None,
    ):
        self.base_url = (base_url or os.environ.get("SEARXNG_BASE_URL", "http://127.0.0.1:8017")).rstrip("/")
        self.timeout = timeout
        self.retries = retries
        self.retry_delays = retry_delays or [5.0, 10.0]

    async def search(
        self,
        query: str,
        limit: int = 10,
        categories: str = "general",
        engines: str = "",
        language: str = "auto",
    ) -> Optional[str]:
        form_data: Dict[str, str] = {
            "q": query,
            "format": "json",
            "language": language,
            "categories": categories,
            "pageno": "1",
        }
        if engines:
            form_data["engines"] = engines

        last_error: Optional[Exception] = None
        for attempt in range(self.retries + 1):
            try:
                async with httpx.AsyncClient(timeout=self.timeout) as client:
                    resp = await client.post(
                        f"{self.base_url}/search",
                        data=form_data,
                    )
                    resp.raise_for_status()
                    data = resp.json()

                    results = data.get("results", [])
                    if not results:
                        suggestions = data.get("suggestions", [])
                        if suggestions:
                            return f"SearXNG suggestions: {', '.join(suggestions)}"
                        return None

                    snippets = []
                    for r in results[:limit]:
                        title = r.get("title", "")
                        url = r.get("url", "")
                        content = r.get("content", "")
                        engine = r.get("engine", "unknown")
                        if content:
                            snippets.append(f"Source [{url}] ({engine}):\n{content[:500]}")

                    if not snippets:
                        return None

                    return f"SearXNG Search ({len(results)} results):\n\n" + "\n\n---\n\n".join(snippets[:5])

            except httpx.HTTPStatusError as e:
                last_error = e
                if e.response.status_code in (429, 502, 503, 504):
                    delay = self.retry_delays[attempt] if attempt < len(self.retry_delays) else self.retry_delays[-1]
                    logger.info(f"SearXNG attempt {attempt + 1}/{self.retries + 1} failed ({e.response.status_code}), retrying in {delay}s")
                    await anyio.sleep(delay)
                else:
                    logger.error(f"SearXNG HTTP error: {e}")
                    raise ProviderError("searxng", f"SearXNG API failure: {e}")
            except httpx.TimeoutException as e:
                last_error = e
                delay = self.retry_delays[attempt] if attempt < len(self.retry_delays) else self.retry_delays[-1]
                logger.info(f"SearXNG attempt {attempt + 1}/{self.retries + 1} timed out, retrying in {delay}s")
                await anyio.sleep(delay)
            except (OmegaError, RuntimeError, OSError) as e:
                last_error = e
                logger.error(f"SearXNG unexpected error: {e}")
                raise ProviderError("searxng", f"SearXNG system failure: {e}")

        logger.error(f"SearXNG exhausted {self.retries + 1} attempts: {last_error}")
        return None

class ExaProvider(SearchProvider):
    """T2: Neural Search (Exa) Provider."""
    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or self._resolve_from_vault()
        self.base_url = "https://api.exa.ai/search"

    @staticmethod
    def _resolve_from_vault() -> str:
        """Fallback to vault if no key passed explicitly."""
        try:
            from omega.vault import KeyVault
            return KeyVault().resolve("exa")
        except (OmegaError, RuntimeError, OSError) as e:
            logger.debug(f"Exa key fallback failed: {e}")
            return os.environ.get("EXA_API_KEY", "")

    async def search(self, query: str, limit: int = 10) -> Optional[str]:
        async with httpx.AsyncClient(timeout=30.0) as client:
            try:
                # [id-soft: quake3-1999] Right Approximation — fast heuristic search provider chain
                # We default to 'auto' type and 'highlights' for token efficiency.
                payload = {
                    "query": query,
                    "numResults": limit,
                    "type": "auto",
                    "contents": {
                        "highlights": True
                    }
                }
                response = await client.post(
                    self.base_url,
                    headers={"x-api-key": self.api_key},
                    json=payload
                )
                if response.status_code == 401:
                    raise ProviderAuthError("exa", "Exa API key invalid")
                if response.status_code == 429:
                    raise ProviderRateLimitError("exa", "Exa rate limit exceeded")
                response.raise_for_status()
                # [IW-3] BLEG: inspect 200 OK bodies for error signatures
                BLEGMiddleware().inspect(
                    status_code=response.status_code,
                    body=response.text,
                    provider="exa",
                    trace_id="unknown",
                    url=str(response.url),
                )

                data = response.json()
                results = data.get("results", [])
                if not results:
                    return None

                # Extract highlights as the primary signal for the triage phase
                snippets = []
                for r in results:
                    content = r.get("highlights", r.get("text", ""))
                    if content:
                        snippets.append(f"Source [{r.get('url')}]:\n{content[:500]}")

                if not snippets:
                    return None

                return f"Exa Neural Search (Highlights):\n\n" + "\n\n---\n\n".join(snippets[:3])
            except ProviderError:
                raise
            except httpx.HTTPStatusError as e:
                logger.error(f"Exa HTTP error: {e}")
                raise ProviderError("exa", f"Exa API failure: {e}")
            except (OmegaError, RuntimeError, OSError) as e:
                logger.error(f"Exa unexpected error: {e}")
                raise ProviderError("exa", f"Exa system failure: {e}")

