class BaseExtractor:
    """Abstract base for all sovereign extractors."""
    async def extract_stream(self, text: str, config: IngestionConfig) -> AsyncGenerator[str, None]:
        raise NotImplementedError

    async def extract(self, text: str, config: IngestionConfig) -> ExtractionSchema:
        """Non-streaming wrapper for extract_stream with robust JSON repair."""
        full_text = ""
        async for chunk in self.extract_stream(text, config):
            full_text += chunk

        # Robust JSON repair and validation
        try:
            repaired_json = repair_json(full_text)
            data = json.loads(repaired_json)
            return ExtractionSchema.model_validate(data)
        except (json.JSONDecodeError, ValidationError, RuntimeError, OSError) as e:
            raise SchemaError(f"Failed to parse extraction result even after repair: {str(e)}")

class GoogleExtractor(BaseExtractor):
    """Google Gemini API extractor with SSE streaming and responseJsonSchema."""

    def __init__(self, api_key: str):
        self.api_key = api_key
        self.base_url = "https://generativelanguage.googleapis.com/v1beta/models"

    @retry(
        stop=stop_after_attempt(3),
        wait=wait_random_exponential(multiplier=1, max=60),
        retry=retry_if_exception_type((ProviderServerError, TransportError)),
        reraise=True
    )
    async def extract_stream(self, text: str, config: IngestionConfig) -> AsyncGenerator[str, None]:
        url = f"{self.base_url}/{config.model_name}:streamGenerateContent?alt=sse"

        prompt = f"Extract data about the entity from the source text below. Focus on technical decisions, personality traits, universal principles, reusable patterns, and training data.\n\n{text[:240000]}"

        payload = {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {
                "temperature": config.temperature,
                "maxOutputTokens": config.max_tokens,
                "responseMimeType": "application/json",
                "responseJsonSchema": EXTRACTION_SCHEMA,
            },
        }

        async with httpx.AsyncClient(timeout=180.0) as client:
            try:
                async with client.stream("POST", url, json=payload, headers={"x-goog-api-key": self.api_key}) as response:
                    if response.status_code == 403:
                        raise SovereigntyError(f"HTTP 403: API Key invalid or quota exceeded. {await response.aread()}")
                    if response.status_code >= 500:
                        raise ProviderServerError(f"HTTP {response.status_code}: Provider internal error.")
                    if response.status_code != 200:
                        raise TransportError(f"HTTP {response.status_code}: Unexpected response.")

                    async for line in response.aiter_lines():
                        if line.startswith("data: "):
                            data_str = line[6:]
                            try:
                                data = json.loads(data_str)
                                parts = data["candidates"][0]["content"]["parts"]
                                for part in parts:
                                    if "text" in part:
                                        yield part["text"]
                            except (json.JSONDecodeError, KeyError, IndexError):
                                continue
            except httpx.RequestError as e:
                raise TransportError(f"Network error during extraction: {str(e)}")

# 🔱 Omega Engine — API Credit Budget Tracker
# AP: AP-BACKGROUND-RESEARCHER-BUDGET-v1.0.0
# ⬡ OMEGA ⬡ MAAT ⬡ sovereign ⬡ budget ⬡ WORKER
#
# Tracks monthly API usage across all search/extraction providers.
# Persists to disk so quotas survive restarts.
#
# NOTE: Tavily, Jina, and Serper budgets removed per D-kal-164.
# Only Exa and Firecrawl remain as active cloud search providers.

# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md
import json
import logging
import os
from dataclasses import dataclass, asdict
from datetime import datetime, timezone
from pathlib import Path

logger = logging.getLogger(__name__)

class APICreditExhausted(Exception):
    """Raised when a provider's monthly quota is exhausted."""
    pass

@dataclass
class ProviderBudget:
    total: int = 1000
    used: int = 0
    reserved_emergency: int = 100

    @property
    def remaining(self) -> int:
        return self.total - self.used

    def consume(self, units: int = 1) -> bool:
        if self.remaining - units < self.reserved_emergency:
            return False
        self.used += units
        return True

    def reset(self):
        self.used = 0

class APICreditBudget:
    """Tracks monthly API credits across all providers.

    Resets on month change automatically. Saves to data/research/credit_budget.json.
    """

    DEFAULT_BUDGETS = {
        "exa": ProviderBudget(total=1000, reserved_emergency=100),
        "firecrawl": ProviderBudget(total=1000, reserved_emergency=100),
    }

    DAILY_LIMITS = {
        "search_ops": 30,
        "deep_extracts": 5,
        "gemma_calls": 20,
    }

    def __init__(self, path: Path = Path("data/research/credit_budget.json")):
        self.path = path
        self.month: str = ""
        self.budgets: dict[str, ProviderBudget] = {}
        self.daily_used: dict[str, int] = {}
        self._today: str = ""
        self._load()

    # ── Public API ──────────────────────────────────────────────────────────

    def has_quota(self, api: str, min_needed: int = 1) -> bool:
        """Check if a provider has enough remaining credits."""
        if api == "search":
            return any(
                p.remaining >= min_needed
                for name, p in self.budgets.items()
                if name in ("exa", "firecrawl")
            )
        budget = self.budgets.get(api)
        if not budget:
            return False
        return budget.remaining >= min_needed

    def consume(self, api: str, units: int = 1) -> None:
        """Consume credits from a provider. Raises APICreditExhausted if insufficient."""
        if api == "search":
            # Exa is the sole cloud search provider (Tavily/Jina/Serper removed per D-kal-164)
            for name in ("exa", "firecrawl"):
                budget = self.budgets.get(name)
                if budget and budget.consume(units):
                    logger.debug(f"Consumed {units} credit(s) from {name}")
                    self._save()
                    return
            raise APICreditExhausted("All search providers exhausted")

        budget = self.budgets.get(api)
        if not budget or not budget.consume(units):
            raise APICreditExhausted(f"{api} exhausted")
        self._save()

    def check_daily_limit(self, operation: str) -> bool:
        """Check if we've hit the daily limit for an operation type."""
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        if self._today != today:
            self.daily_used = {}
            self._today = today
        limit = self.DAILY_LIMITS.get(operation, float("inf"))
        used = self.daily_used.get(operation, 0)
        return used < limit

    def increment_daily(self, operation: str) -> None:
        """Increment daily counter for an operation type."""
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        if self._today != today:
            self.daily_used = {}
            self._today = today
        self.daily_used[operation] = self.daily_used.get(operation, 0) + 1

    def get_status(self) -> dict:
        """Return a snapshot of current budget state for reporting."""
        return {
            "month": self.month,
            "daily_used": dict(self.daily_used),
            "budgets": {
                name: {
                    "total": b.total,
                    "used": b.used,
                    "remaining": b.remaining,
                    "reserved": b.reserved_emergency,
                }
                for name, b in self.budgets.items()
            },
        }

    def select_search_provider(self) -> str:
        """Select the best available search provider based on remaining quota."""
        # Exa is the sole cloud search provider (Tavily/Jina/Serper removed per D-kal-164)
        for name in ("exa", "firecrawl"):
            budget = self.budgets.get(name)
            if budget and budget.remaining > budget.reserved_emergency:
                return name
        # Fall back to anything with remaining credits
        for name, budget in self.budgets.items():
            if budget and budget.remaining > 0:
                return name
        raise APICreditExhausted("All search providers exhausted")

    # ── Persistence ─────────────────────────────────────────────────────────

    def _load(self) -> None:
        """Load budget state from disk. Reset if month changed."""
        current_month = datetime.now(timezone.utc).strftime("%Y-%m")
        if self.path.exists():
            try:
                data = json.loads(self.path.read_text())
                if data.get("month") == current_month:
                    self.month = current_month
                    self.budgets = {
                        name: ProviderBudget(**b)
                        for name, b in data.get("budgets", {}).items()
                    }
                    self.daily_used = data.get("daily_used", {})
                    self._today = data.get("today", "")
                    return
            except (json.JSONDecodeError, KeyError, TypeError):
                logger.warning("Corrupted credit budget file, resetting.")
        self._reset_month()

    def _save(self) -> None:
        """Persist budget state to disk atomically."""
        self.path.parent.mkdir(parents=True, exist_ok=True)
        data = {
            "month": self.month,
            "today": self._today,
            "daily_used": self.daily_used,
            "budgets": {name: asdict(b) for name, b in self.budgets.items()},
        }
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(data, indent=2))
        tmp.replace(self.path)

    def _reset_month(self) -> None:
        """Reset all budgets for a new month."""
        self.month = datetime.now(timezone.utc).strftime("%Y-%m")
        self.budgets = {name: ProviderBudget(**asdict(b)) for name, b in self.DEFAULT_BUDGETS.items()}
        self.daily_used = {}
        self._today = ""
        self._save()
        logger.info(f"Credit budgets reset for {self.month}")

# AP: AP-STATE-MANAGER-v1.0.0
# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md import os import hashlib import shutil import logging from typing import Dict, Any, Optional, Tuple from dataclasses import dataclass from pathlib import Path
import anyio from omega.errors import OmegaError from anyio.to_thread import run_sync
logger = logging.getLogger("omega.state_manager")
@dataclass class SomaticStateKey: """Unique identifier for a binary model state.""" model_hash: str session_id: str kv_size: int version: str = "1.0.0"
class CASBlobStore: """ Content Addressable Storage for engine state. Implements M12 (Queue Integrity) via atomic renames. """ def __init__(self, base_dir: str = "data/somatic/blobs"): self.base_dir = Path(base_dir) self._ensure_dir()
def _ensure_dir(self): self.base_dir.mkdir(parents=True, exist_ok=True)
async def put(self, data: bytes) -> str: """Writes data to a blob and returns its SHA256 hash.""" blob_hash = hashlib.sha256(data).hexdigest() blob_path = self.base_dir / f"{blob_hash}.bin"
if blob_path.exists(): return blob_hash
tmp_path = blob_path.with_suffix(".tmp") try: await run_sync(self._write_atomic, tmp_path, blob_path, data) except (OmegaError, RuntimeError, OSError) as e: logger.error(f"Failed to write blob {blob_hash}: {e}") raise
return blob_hash
def _write_atomic(self, tmp_path: Path, final_path: Path, data: bytes): with open(tmp_path, "wb") as f: f.write(data) f.flush() os.fsync(f.fileno()) os.rename(tmp_path, final_path)
async def get(self, blob_hash: str) -> bytes: """Reads a blob by its hash.""" blob_path = self.base_dir / f"{blob_hash}.bin" if not blob_path.exists(): raise FileNotFoundError(f"Blob {blob_hash} not found in CAS")
return await run_sync(self._read_blob, blob_path)
def _read_blob(self, path: Path) -> bytes: with open(path, "rb") as f: return f.read()
async def exists(self, blob_hash: str) -> bool: return await run_sync(lambda: (self.base_dir / f"{blob_hash}.bin").exists())
class SomaticStateSerializer: """ High-fidelity binary state serialization for llama-cpp-python. Implements M20 (SomaticState). """ def __init__(self, model: any): self.model = model
async def capture_state(self) -> bytes: """Captures the current KV cache state using the C-API.""" return await run_sync(self._capture)
def _capture(self) -> bytes: # Use the low-level C-API bindings for maximum fidelity # llama_get_state_size -> llama_copy_state_data import llama_cpp try: size = llama_cpp.llama_cpp.llama_get_state_size(self.model.model) buffer = bytearray(size) llama_cpp.llama_cpp.llama_copy_state_data(self.model.model, buffer) return bytes(buffer) except (OmegaError, RuntimeError, OSError) as e: logger.error(f"Somatic capture failed: {e}") raise
async def apply_state(self, state_data: bytes): """Restores the KV cache state using the C-API.""" await run_sync(self._apply, state_data)
def _apply(self, data: bytes): import llama_cpp try: # Verify size before applying to prevent segfaults expected_size = llama_cpp.llama_cpp.llama_get_state_size(self.model.model) if len(data) != expected_size: raise ValueError(f"Somatic state size mismatch: expected {expected_size}, got {len(data)}")
llama_cpp.llama_cpp.llama_set_state_data(self.model.model, data) except (OmegaError, RuntimeError, OSError) as e: logger.error(f"Somatic apply failed: {e}") raise
class UnifiedStateManager: """ The facade for managing all engine state. Coordinates between CAS, SomaticState, and Entity Memory. """ def __init__(self, model: any, base_dir: str = "data/somatic"): self.blob_store = CASBlobStore() self.somatic = SomaticStateSerializer(model) self.base_dir = Path(base_dir) self._ensure_dir()
def _ensure_dir(self): self.base_dir.mkdir(parents=True, exist_ok=True)
async def freeze(self, entity_id: str, memory_data: bytes, session_data: bytes) -> str: """ Captures a full cognitive snapshot. Returns a master hash of the state bundle. """ # 1. Capture binary model state somatic_blob = await self.somatic.capture_state() somatic_hash = await self.blob_store.put(somatic_blob)
# 2. Store memory and session as blobs mem_hash = await self.blob_store.put(memory_data) sess_hash = await self.blob_store.put(session_data)
# 3. Create a state bundle manifest bundle = { "entity_id": entity_id, "somatic_hash": somatic_hash, "memory_hash": mem_hash, "session_hash": sess_hash, "timestamp": anyio.current_time() if hasattr(anyio, 'current_time') else None, }
import json bundle_data = json.dumps(bundle, sort_keys=True).encode() return await self.blob_store.put(bundle_data)
async def resume(self, bundle_hash: str): """ Restores a full cognitive snapshot. """ # 1. Load bundle manifest bundle_data = await self.blob_store.get(bundle_hash) import json bundle = json.loads(bundle_data)
# 2. Restore binary state first somatic_blob = await self.blob_store.get(bundle['somatic_hash']) await self.somatic.apply_state(somatic_blob)
# 3. Return memory and session data for the engine to load return { "memory": await self.blob_store.get(bundle['memory_hash']), "session": await self.blob_store.get(bundle['session_hash']), "entity_id": bundle['entity_id'] }

"""Sovereign Soul Staging Gate TUI.
AP: AP-SOUL-STAGE-v1.0.0

Allows the user to review, approve, or reject proposed L3 principles
before they are committed to an entity's soul.yaml.
"""
# DocRef: docs/architecture/SOUL_ARCHITECTURE_PROTOCOL.md

import anyio
from textual.app import App, ComposeResult
from textual.widgets import Header, Footer, Static, DataTable, Button, Input, Label
from textual.containers import Container, Horizontal, Vertical
from textual.binding import Binding

from omega.oracle.entity_registry import EntityRegistry
from omega.state import get_usm

class SoulStageApp(App):
    """TUI for staging soul distillation proposals."""
    CSS = """
    Screen {
        align: center middle;
    }
    #main_container {
        width: 90%;
        height: 90%;
        border: solid green;
        padding: 1;
    }
    .proposal_detail {
        border: double white;
        padding: 1;
        margin: 1;
        height: auto;
    }
    .action_bar {
        height: 3;
        align: center middle;
    }
    """

    BINDINGS = [
        Binding("q", "quit", "Quit"),
        Binding("a", "approve", "Approve"),
        Binding("r", "reject", "Reject"),
        Binding("d", "defer", "Defer"),
    ]

    def __init__(self, entity_name: str):
        super().__init__()
        self.entity_name = entity_name
        self.registry = EntityRegistry()
        self.usm = get_usm()
        self.current_proposal = None

    def compose(self) -> ComposeResult:
        yield Header()
        with Container(id="main_container"):
            yield Label(f"Sovereign Soul Staging: {self.entity_name}")
            yield DataTable(id="proposal_table")
            with Vertical(classes="proposal_detail", id="detail_view"):
                yield Label("Select a proposal to review...")
            with Horizontal(classes="action_bar"):
                yield Button("Approve", id="btn_approve", variant="success")
                yield Button("Reject", id="btn_reject", variant="error")
                yield Button("Defer", id="btn_defer", variant="warning")
        yield Footer()

    async def on_mount(self) -> None:
        await self.load_proposals()

    async def load_proposals(self) -> None:
        """Load proposed lessons from proposed_lessons.yaml."""
        table = self.query_one("#proposal_table", DataTable)
        table.clear()
        table.add_columns("ID", "L1 Narrative", "L2 Insight", "L3 Principle")

        # In a real implementation, this reads from proposed_lessons.yaml
        # For now, we mock some data to verify the TUI
        mock_proposals = [
            {
                "id": "prop_001",
                "L1": "Observed that local inference is 10x faster for 1.7B models.",
                "L2": "Small models are sufficient for routing tasks.",
                "L3": "The Right Approximation: Use the smallest model that meets the precision requirement."
            },
            {
                "id": "prop_002",
                "L1": "SomaticState capture caused a segfault in llama-cpp.",
                "L2": "C-FFI calls are unstable in the main thread.",
                "L3": "Sovereign Isolation: Wrap all C-FFI in isolated processes."
            }
        ]

        for p in mock_proposals:
            table.add_row(p["id"], p["L1"][:50] + "...", p["L2"][:50] + "...", p["L3"][:50] + "...")

        self.proposals = mock_proposals

    def on_data_table_row_selected(self, event: DataTable.RowSelected) -> None:
        proposal = self.proposals[event.cursor_row]
        self.current_proposal = proposal
        detail = self.query_one("#detail_view", Vertical)
        detail.children.clear()
        detail.mount(Label(f"ID: {proposal['id']}"))
        detail.mount(Label(f"\n[L1 Narrative]\n{proposal['L1']}"))
        detail.mount(Label(f"\n[L2 Insight]\n{proposal['L2']}"))
        detail.mount(Label(f"\n[L3 Principle]\n{proposal['L3']}"))

    async def action_approve(self) -> None:
        if self.current_proposal:
            # Logic to move from proposed_lessons.yaml to soul.yaml
            self.notify(f"Approved {self.current_proposal['id']}")
            # Implementation: update soul.yaml

    async def action_reject(self) -> None:
        if self.current_proposal:
            self.notify(f"Rejected {self.current_proposal['id']}")

    async def action_defer(self) -> None:
        if self.current_proposal:
            self.notify(f"Deferred {self.current_proposal['id']}")

    async def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "btn_approve":
            await self.action_approve()
        elif event.button.id == "btn_reject":
            await self.action_reject()
        elif event.button.id == "btn_defer":
            await self.action_defer()

if __name__ == "__main__":
    # Example usage
    app = SoulStageApp(entity_name="sophia")
    app.run()

# AP: AP-ORACLE-RESTORE-v2.3.0
# 🔱 Iris Intent Matcher
# AP: AP-NOVA-MATCHER-v1.0.0
# Lightweight intent detection for the always-on Iris container.

# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md
import re
from typing import Optional, Tuple

class IntentMatcher:
    """Detects user intent from query text."""

    # Patterns for entity-less routing
    GREETING = re.compile(r"^\b(hi|hello|hey|greetings|good\s+(morning|afternoon|evening))\b", re.IGNORECASE)
    FAREWELL = re.compile(r"^\b(bye|goodbye|exit|quit|thanks?|thank you)\b", re.IGNORECASE)
    HELP = re.compile(r"^\b(help|what can you do|commands|how do i)\b[?.]*$", re.IGNORECASE)

    # Voice-specific patterns
    REPEAT = re.compile(r"(repeat|say that again|what did you say)", re.IGNORECASE)
    VOLUME = re.compile(r"(volume|louder|softer|quieter)", re.IGNORECASE)
    SPEED = re.compile(r"(speed|faster|slower)", re.IGNORECASE)

    # @summon pattern: single word entity name only
    AT_SUMMON = re.compile(r"^@(\w+)[,:\s]+(.+)$", re.IGNORECASE)
    # Hey/Summon + multi-word entity until comma or colon
    HEY_SUMMON = re.compile(r"^(?:hey\s+|summon\s+)(.+?)[,:]\s*(.*)$", re.IGNORECASE)

    def classify(self, text: str) -> Tuple[str, Optional[str]]:
        """Classify intent and return (intent_type, entity_name).

        Returns:
            ("summon", entity_name) — explicit entity summon
            ("domain", None) — needs domain routing
            ("direct", None) — Iris can answer directly
            ("voice_cmd", None) — voice control command
        """
        # Check for @summon pattern (@Entity query)
        match = self.AT_SUMMON.match(text.strip())
        if match:
            return ("summon", match.group(1).strip())

        # Check for Hey Entity or Summon Entity patterns
        match = self.HEY_SUMMON.match(text.strip())
        if match:
            return ("summon", match.group(1).strip())

        # Check for voice commands
        if self.REPEAT.search(text):
            return ("voice_cmd", "repeat")
        if self.VOLUME.search(text):
            return ("voice_cmd", "volume")
        if self.SPEED.search(text):
            return ("voice_cmd", "speed")

        # Check for greetings/farewells (Iris can handle directly)
        if self.GREETING.match(text):
            return ("direct", None)
        if self.FAREWELL.match(text):
            return ("direct", None)

        # Route everything else to Oracle domain matching
        return ("domain", None)

    def is_iris_capable(self, text: str) -> bool:
        """Can Iris answer this directly without routing to a Pillar Keeper?"""
        return bool(
            self.GREETING.match(text)
            or self.FAREWELL.match(text)
            or self.HELP.search(text)
        )

    def iris_response(self, text: str) -> Optional[str]:
        """Generate a direct response from Iris for simple queries."""
        if self.GREETING.match(text):
            return "Greetings, seeker. I am Iris, your voice interface. Speak your question, and I will carry it to the one who knows."
        if self.FAREWELL.match(text):
            return "May your path be illuminated. Call on me anytime."
        if self.HELP.search(text):
            return (
                "I can help you connect with any entity in your active IWAD. Try:\n"
                "  'summon [entity name]' — to converse with a specific entity\n"
                "  'ask [entity] about [topic]' — for expert guidance on a topic\n"
                "  '@[entity] [query]' — quick summon syntax\n"
                "  'add-entity [name]' — to create your own custom entity"
            )
        return None

# AP: AP-TIMEOUT-MGR-v1.0.0 # AP: AP-TIMEOUT-MGR-v1.0.0 # 🔱 Timeout Manager — 4-Layer Nested Cancellation Hierarchy # Ported from xna-omega-legacy/scripts/ssa/timeout_manager.py
# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md import anyio import logging import time from typing import Optional, Callable, Any, Dict from dataclasses import dataclass, field
logger = logging.getLogger(__name__)
@dataclass class TimeoutContext: """Context for a specific timeout layer.""" name: str timeout: float start_time: float = field(default_factory=time.time) cancelled: bool = False
class TimeoutManager: """ Implements a 4-layer nested cancellation hierarchy: Tool -> Group -> Turn -> Workflow
If a higher layer times out, all nested lower layers are immediately cancelled. """
def __init__(self): self._layers = { "workflow": 300.0, # 5 mins "turn": 60.0, # 1 min "group": 30.0, # 30 secs "tool": 10.0, # 10 secs } self._active_contexts: Dict[str, TimeoutContext] = {}
async def execute(self, layer: str, func: Callable, *args, **kwargs) -> Any: """Executes a function within a specific timeout layer.""" if layer not in self._layers: raise ValueError(f"Invalid timeout layer: {layer}. Must be one of {list(self._layers.keys())}")
timeout = self._layers[layer] ctx = TimeoutContext(name=layer, timeout=timeout) self._active_contexts[layer] = ctx
try: # [AnyIO 4.x] fail_after is a synchronous context manager with anyio.fail_after(timeout): return await func(*args, **kwargs) except TimeoutError: logger.warning(f"Timeout reached at {layer} layer ({timeout}s)") ctx.cancelled = True raise finally: if layer in self._active_contexts and self._active_contexts[layer] == ctx: del self._active_contexts[layer]
def set_timeout(self, layer: str, seconds: float): """Update the timeout for a specific layer.""" if layer in self._layers: self._layers[layer] = seconds logger.info(f"Timeout for {layer} updated to {seconds}s") else: raise ValueError(f"Invalid layer: {layer}")
def get_timeout(self, layer: str) -> float: """Get current timeout for a layer.""" return self._layers.get(layer, 0.0)

# 🔱 Omega Engine — Background Researcher Metrics
# AP: AP-JEM-METRICS-v1.0.0
# ⬡ OMEGA ⬡ MAAT ⬡ metrics ⬡ PHASE-2

# DocRef: docs/architecture/ORACLE_DEEP_DIVE.md
import json
import os
import anyio
from datetime import datetime, timezone
from typing import Dict, Any
from pathlib import Path

class ResearchMetrics:
    """Logs per-cycle performance and quality metrics for the 3-tier pipeline.

    Outputs to JSONL files for later analysis and synthetic dataset auditing.
    """

    def __init__(self, log_dir: str = "data/research/metrics"):
        self.log_dir = Path(log_dir)
        self.log_dir.mkdir(parents=True, exist_ok=True)
        self.log_file = self.log_dir / "cycle_metrics.jsonl"

    async def log_cycle(self, topic: str, metrics: Dict[str, Any]):
        """Log a research cycle's metrics to the JSONL store."""
        timestamp = datetime.now(timezone.utc).isoformat()
        entry = {
            "timestamp": timestamp,
            "topic": topic,
            **metrics
        }

        def _write():
            with open(self.log_file, "a") as f:
                f.write(json.dumps(entry) + "\n")

        await anyio.to_thread.run_sync(_write)

    def get_summary(self) -> Dict[str, Any]:
        """Calculate aggregate performance metrics from the log file."""
        if not self.log_file.exists():
            return {"status": "no logs found"}

        cycles = []
        with open(self.log_file, 'r') as f:
            for line in f:
                try:
                    cycles.append(json.loads(line))
                except json.JSONDecodeError:
                    continue

        if not cycles:
            return {"status": "empty logs"}

        return {
            "total_cycles": len(cycles),
            "avg_t1_latency": sum(c.get("t1_latency", 0) for c in cycles) / len(cycles),
            "avg_t2_latency": sum(c.get("t2_latency", 0) for c in cycles) / len(cycles),
            "avg_t3_latency": sum(c.get("t3_latency", 0) for c in cycles) / len(cycles),
            "success_rate": sum(1 for c in cycles if c.get("t3_quality", 0) > 0.7) / len(cycles)
        }

